Per_Exec_Wake sense_rs_pi_loop( void *dummy , Sense_Rs_Input *input )
{
    if( ied_detect( input->ied , sense_rs_pi_status(input->selector) ) )
    {
        sense_rs_pi_executor( input->selector,FALSE, ied_get_level(input->ied));

        return PER_EXEC_WAKE ; 
    }

    return PER_EXEC_SLEEP ;
}


